import { focus } from "../../helpers";
import { StyleFn } from "..";

export const Link: StyleFn = (theme, mode) => {
  const {
    color,
    font,
    opacity,
    size: { spacing },
  } = theme;
  const { focusWithPseudo } = focus(theme, mode);

  return {
    root: {
      extend: [focusWithPseudo()],
      cursor: "pointer",
      textDecoration: "underline",
      fontFamily: "inherit",
      // disable the focus ring for mouse, touch and keyboard users
      outline: 0,
      display: "inline-flex",
      boxSizing: "border-box",
      position: "relative",
      fontWeight: font.weight.bold,
      fontSize: font.size.medium,
      lineHeight: "inherit", //TODO: to be improved in v4
      padding: `calc(${spacing[2]} + 1px) ${spacing[8]}`,
      borderRadius: 3,
      color: color.text.link.neutral.default[mode],
      "&:hover": { color: color.text.link.neutral.hover[mode] },
      "&:active": { color: color.text.link.neutral.active[mode] },
      "&:visited": { color: color.text.link.neutral.visited[mode] },
    },
    _negative: {
      color: mode == "dark" ? "#ffffff" : "#fff", // Workaround for dark mode
      "&:hover": { color: color.text.link.negative.brighterhover[mode] },
      "&:active": { color: color.text.link.negative.brighteractive[mode] },
      "&:visited": { color: color.text.link.negative.visited[mode] },
      extend: [focusWithPseudo({ colorForce: color.palette.skyblue[10] })],
    },
    _xsmall: {
      fontSize: font.size.xsmall,
      lineHeight: "inherit", //TODO: to be improved in v4
      padding: `calc(${spacing[2]} + 1px) ${spacing[4]}`,
      fontWeight: font.weight.regular,
    },
    _small: {
      fontSize: font.size.small,
      lineHeight: "inherit", //TODO: to be improved in v4
      padding: `calc(${spacing[2]} + 1px) ${spacing[8]}`,
    },
    _medium: {},
    _large: {
      fontSize: font.size.large,
      lineHeight: "inherit", //TODO: to be improved in v4
      padding: `calc(${spacing[4]} - 1px) ${spacing[8]}`,
    },
    _inline: {
      "&$_inline": {
        border: 0,
        padding: `calc(${spacing[2]} + 1px) 0`,
      },
    },
    _disabled: {
      opacity: opacity.disabled,
      pointerEvents: "none",
    },
  };
};
